// Sticky-totals summary model (O-096 / CMP-H05) — pure derivations for
// FoundationTotals: the separate cost/sell/margin trio, the itemized takeoff,
// and the missing-input checklist. No React, no entity access, no imports —
// identical input produces identical output, so the whole surface is
// unit-testable under Node.
//
// Held/acknowledged contract (mirrors calc + BOM surfaces):
//   • A held component keeps its acknowledged snapshot amounts; rows that
//     display them are flagged `held` so the UI can label "(saved)".
//   • A non-finite amount is unavailable — the model returns null and the UI
//     renders "Not saved"/"—"; nothing is laundered to $0 or guessed.
//   • Margin is only produced when BOTH sides are actually known — never a
//     fabricated margin on a held or projected value. When the applied
//     customer_pricing snapshot carries its own internal cost
//     (raw_subtotal), the acknowledged cost-vs-sell pair is exposed too.

const fin = (v) => typeof v === "number" && Number.isFinite(v);
const numOrNull = (v) =>
  v === undefined || v === null || v === "" ? null : Number.isFinite(Number(v)) ? Number(v) : null;
const arr = (v) => (Array.isArray(v) ? v : []);
const isRecord = (v) => !!v && typeof v === "object" && !Array.isArray(v);
const fmtQty = (n, unit, digits = 2) =>
  fin(n) ? `${n.toLocaleString(undefined, { maximumFractionDigits: digits })} ${unit}` : null;
const joinQty = (parts) => {
  const out = parts.filter((p) => typeof p === "string" && p !== "");
  return out.length ? out.join(" · ") : null;
};

// ─── Persisted split-total partition ─────────────────────────────────────────
// The same 12-field partition O-010 established (FOUNDATION_RECORD_TOTAL_FIELDS
// in builderService.js — kept in sync there; the model test asserts parity).
// total_brick_cost / total_fill_cost are subsets of total_wall_cost and are
// NEVER counted separately. A non-finite partition field is a held bucket:
// the checklist enumerates it instead of pretending the amount exists.
export const FOUNDATION_STICKY_PARTITION_FIELDS = [
  ["total_concrete_cost", "Concrete"],
  ["total_rebar_cost", "Rebar"],
  ["total_excavation_cost", "Excavation"],
  ["total_forming_materials_cost", "Forming materials"],
  ["total_labor_cost", "Labor"],
  ["total_wall_cost", "Walls"],
  ["total_pole_cost", "Poles"],
  ["total_pole_painting_cost", "Pole painting"],
  ["total_equipment_cost", "Equipment"],
  ["total_wall_cap_cost", "Wall caps"],
  ["total_signage_cabinet_cost", "Signage cabinets"],
  ["total_landscape_cost", "Site landscaping"],
];

const FOUNDATION_TYPE_LABEL = {
  spread_foot: "spread footing",
  pillar: "pillar/caisson",
};

// ─── Sticky cost / sell / margin ─────────────────────────────────────────────
//
// Sell precedence mirrors customerPricing.sourceProjectEconomics' foundation
// branch exactly: pricing engine > applied tier snapshot > price override >
// markup %. The engine side is injectable (engineResolver = the
// foundationEngineEconomics seam) so this module stays import-free; callers
// pass the real resolver when a record is wired and null otherwise.
//
// Held-safety rules:
//   • override and applied-tier sell are recorded values — they display even
//     while pricing is paused (they are the acknowledged sell, not a guess).
//   • the manual markup baseline requires the LIVE internal cost — a markup
//     projected over a held amount would fabricate a customer price, so it
//     resolves "none" while only a saved cost remains.
//   • margin requires a known cost AND a known sell; basis labels which cost
//     was compared ("live" vs "saved").

export function resolveFoundationStickySummary({
  sectionTotal = null,
  savedSectionTotal = null,
  pricingUnavailable = false,
  project = null,
  engineResolver = null,
} = {}) {
  const liveCost = fin(sectionTotal) ? sectionTotal : null;
  const savedCost = fin(savedSectionTotal) ? savedSectionTotal : null;
  const cost = liveCost !== null ? liveCost : savedCost;
  const costSource = liveCost !== null ? "live" : savedCost !== null ? "saved" : "none";

  const projectLinked = project !== null && project !== undefined;
  const markupPercent = numOrNull(project?.customer_markup_percent) ?? 0;
  const override = numOrNull(project?.customer_price_override);
  const cp = isRecord(project?.customer_pricing) ? project.customer_pricing : null;
  const tierTotal = cp?.applied === true && numOrNull(cp?.total) !== null ? numOrNull(cp.total) : null;
  const tierCost = numOrNull(cp?.raw_subtotal);

  // Manual baseline = exactly the panel/economics formula — but only against
  // the live cost AND only when the record is actually wired: with no project
  // prop the recorded markup/override are unknown, so an implicit 0% sell
  // would fabricate a customer price. Held-only cost leaves it unresolved too.
  const manualBaseline = projectLinked && liveCost !== null
    ? (override !== null && override > 0 ? override : liveCost * (1 + markupPercent / 100))
    : null;

  let sell = null;
  let sellSource = "none";
  let sellLabel = "Not recorded";

  // Engine resolution is gated on a live baseline the same way the manual
  // markup is: with the internal cost held, an engine number computed against
  // a forced-zero baseline would be a fabricated sell, not a recorded one.
  if (projectLinked && typeof engineResolver === "function" && manualBaseline !== null) {
    let wired = null;
    try {
      wired = engineResolver(project, {
        baselineSell: manualBaseline,
        internalCost: cost,
        markupPercent,
      });
    } catch {
      wired = null;
    }
    if (wired && fin(wired.customerPrice)) {
      sell = wired.customerPrice;
      sellSource = "engine";
      sellLabel = "Pricing engine";
    }
  }
  if (sell === null && tierTotal !== null) {
    sell = tierTotal;
    sellSource = "tier";
    sellLabel = `Tier ${cp.tier_number ?? "—"} applied`;
  }
  if (sell === null && override !== null && override > 0) {
    sell = override;
    sellSource = "override";
    sellLabel = "Price override";
  }
  if (sell === null && manualBaseline !== null) {
    sell = manualBaseline;
    sellSource = "markup";
    sellLabel = markupPercent > 0 ? `Markup ${markupPercent}%` : "Cost (no markup)";
  }

  const marginAmount = sell !== null && cost !== null ? sell - cost : null;
  const marginPct = marginAmount !== null && sell > 0 ? (marginAmount / sell) * 100 : null;
  const marginBasis = marginAmount !== null ? costSource : "none";

  // Acknowledged pair straight from the snapshot fields: when the applied
  // tier recorded both its sell total and the internal cost it was computed
  // on, that pair is the margin the customer actually accepted — shown as a
  // footnote when it diverges from the cost displayed.
  const acknowledged = sellSource === "tier" && fin(tierCost)
    ? {
        sell: tierTotal,
        cost: tierCost,
        marginAmount: tierTotal - tierCost,
        marginPct: tierTotal > 0 ? ((tierTotal - tierCost) / tierTotal) * 100 : null,
        differs: cost === null || Math.abs(tierCost - cost) > 0.005,
      }
    : null;

  return {
    cost: { value: cost, source: costSource },
    sell: { value: sell, source: sellSource, label: sellLabel },
    margin: { amount: marginAmount, pct: marginPct, basis: marginBasis },
    acknowledged,
    projectLinked,
    pricingUnavailable: pricingUnavailable === true,
  };
}

// ─── Itemized takeoff ────────────────────────────────────────────────────────
//
// Itemized = per-component rows grouped by section, each carrying the
// quantity basis and its own amount. Rows a held component leaves behind are
// flagged `held` (acknowledged snapshot shown) and amountless held rows keep
// `amount: null` → the UI renders "Not saved", never $0.
//
// Data slices are passed in so the module stays import-free; the component
// supplies calc.* (items/walls/poles/caps/equipment/delivery/pricing flags)
// and project-derived rows (cabinets, landscape) when wired.

export function buildFoundationTakeoff({
  totals = {},
  items = null,
  itemPricing = null,
  walls = null,
  wallPricing = null,
  poles = null,
  polePricing = null,
  wallCaps = null,
  equipment = null,
  equipmentPricing = null,
  delivery = null,
  cabinets = null,
  cabinetRows = null,
  landscapeLines = null,
  landscapePricing = null,
} = {}) {
  const groups = [];
  const addGroup = (key, label, rows) => {
    if (rows.length) groups.push({ key, label, rows });
  };

  // ── Foundations: one row per item + the delivery order row ──
  const foundationRows = [];
  arr(items).forEach((item, index) => {
    const held = arr(itemPricing)[index]?.available === false;
    const typeLabel = FOUNDATION_TYPE_LABEL[item?.foundation_type] || "foundation";
    const qty = joinQty([
      fmtQty(numOrNull(item?.concrete_volume_cy), "CY"),
      numOrNull(item?.rebar_feet) > 0 ? fmtQty(numOrNull(item.rebar_feet), "LF rebar", 1) : null,
      numOrNull(item?.forming_qty) > 0 ? fmtQty(numOrNull(item.forming_qty), "forming", 1) : null,
      numOrNull(item?.excavation_volume_cy) > 0 ? fmtQty(numOrNull(item.excavation_volume_cy), "CY dug") : null,
    ]);
    foundationRows.push({
      key: `item-${index}`,
      label: `Item ${index + 1} — ${typeLabel} ×${numOrNull(item?.quantity) ?? 1}`,
      qty,
      amount: fin(item?.item_total_cost) ? item.item_total_cost : null,
      held,
    });
  });
  const deliveryRows = (() => {
    // Live delivery from calc when wired; otherwise the totals snapshot fields.
    const src = isRecord(delivery) ? delivery : null;
    const yards = src ? numOrNull(src.roundedYards) : numOrNull(totals?.concrete_delivered_yards);
    const trucks = src ? arr(src.trucksList).length : arr(totals?.concrete_trucks).length;
    const amount = src ? numOrNull(src.concreteTotal) : numOrNull(totals?.concrete_delivery_cost);
    const held = src?.pricingUnavailable === true;
    if (yards === null && !trucks && amount === null) return [];
    return [{
      key: "delivery",
      label: "Concrete delivery",
      qty: joinQty([
        yards !== null ? fmtQty(yards, "yd", 1) : null,
        trucks > 0 ? `${trucks} truck${trucks === 1 ? "" : "s"}` : null,
        fin(numOrNull(src?.additionalStopsCost ?? totals?.additional_stops_cost)) && numOrNull(src?.additionalStopsCost ?? totals?.additional_stops_cost) > 0
          ? "+ extra stops" : null,
      ]),
      amount,
      held,
    }];
  })();
  addGroup("foundations", "Foundations", [...foundationRows, ...deliveryRows]);

  // ── Masonry walls: one row per wall, material + labor + internal fill ──
  addGroup("masonry", "Masonry walls", arr(walls).map((wall, index) => {
    const held = arr(wallPricing)[index]?.available === false;
    const cc = isRecord(wall?.calculatedCosts) ? wall.calculatedCosts : {};
    const matUnit = cc.materialQuantityUnit === "cy" ? "CY" : "units";
    const linearFt = numOrNull(cc.totalLinearInches);
    const qty = joinQty([
      numOrNull(cc.totalBricks) !== null ? fmtQty(numOrNull(cc.totalBricks), matUnit, 0) : null,
      linearFt !== null ? fmtQty(linearFt / 12, "LF outline", 1) : null,
      numOrNull(cc.internalTotalBricks) > 0
        ? `+${fmtQty(numOrNull(cc.internalTotalBricks), cc.internalMaterialQuantityUnit === "cy" ? "CY" : "units", 0)} internal`
        : null,
    ]);
    return {
      key: `wall-${index}`,
      label: wall?.name || `Wall ${index + 1}`,
      qty,
      amount: fin(cc.totalCost) ? cc.totalCost : null,
      held,
    };
  }));

  // ── Poles: billed required length + stock count (+ painting flag) ──
  addGroup("poles", "Poles", arr(poles).map((pole, index) => {
    const held = arr(polePricing)[index]?.available === false;
    const billedInches = numOrNull(pole?.required_length_inches)
      ?? (numOrNull(pole?.height_inches) !== null && numOrNull(pole?.embedment_inches ?? pole?.y_offset_inches) !== null
        ? numOrNull(pole.height_inches) + numOrNull(pole.embedment_inches ?? pole?.y_offset_inches)
        : null);
    const qty = joinQty([
      billedInches !== null ? fmtQty(billedInches / 12, "LF billed", 1) : null,
      numOrNull(pole?.stock_pieces) > 0 ? `${numOrNull(pole.stock_pieces)} stock pc${numOrNull(pole.stock_pieces) === 1 ? "" : "s"}` : null,
      numOrNull(pole?.pole_painting_cost) > 0 ? "+ painting" : null,
    ]);
    return {
      key: `pole-${index}`,
      label: pole?.pole_name || `Pole ${index + 1}`,
      qty,
      amount: fin(pole?.total_cost) ? pole.total_cost : null,
      held,
    };
  }));

  // ── Wall caps: per-piece rows when calc is wired; per-material rollup
  //    from the totals snapshot otherwise ──
  const capRows = (() => {
    if (Array.isArray(wallCaps) && wallCaps.length) {
      return wallCaps.map((cap, index) => {
        const cut = numOrNull(cap?.length_inches ?? cap?.cut_length_inches);
        return {
          key: `cap-${index}`,
          label: cap?.cap_name || `Cap ${index + 1}`,
          qty: joinQty([cut !== null ? fmtQty(cut, "in cut", 1) : null]),
          amount: fin(cap?.cost) ? cap.cost : null,
          held: !fin(cap?.cost),
        };
      });
    }
    return arr(totals?.wall_caps_by_material).map((g, index) => ({
      key: `capmat-${index}`,
      label: g?.name || `Wall cap material ${index + 1}`,
      qty: numOrNull(g?.qty) !== null ? `${numOrNull(g.qty)} pcs` : null,
      amount: fin(g?.cost) ? g.cost : null,
      held: !fin(g?.cost),
    }));
  })();
  addGroup("wall_caps", "Wall caps", capRows);

  // ── Equipment rentals: period + duration + delivery flag ──
  addGroup("equipment", "Equipment", arr(equipment).map((entry, index) => {
    const held = arr(equipmentPricing)[index]?.available === false;
    const duration = numOrNull(entry?.custom_qty ?? entry?.rental_duration) ?? 1;
    const period = entry?.rental_period || "day";
    const qty = joinQty([
      fmtQty(duration, period, 1),
      entry?.include_delivery ? "+ delivery" : null,
    ]);
    return {
      key: `equip-${index}`,
      label: `Equipment ${index + 1}`,
      qty,
      amount: fin(entry?.equipment_cost) ? entry.equipment_cost : null,
      held,
    };
  }));

  // ── Signage cabinets (page-level extras; priced rows passed in) ──
  addGroup("cabinets", "Signage cabinets", arr(cabinetRows).map((row, index) => {
    const cabinet = arr(cabinets)[index] || {};
    const quantity = cabinet.quantity === undefined || cabinet.quantity === null || cabinet.quantity === ""
      ? 1 : numOrNull(cabinet.quantity);
    return {
      key: `cabinet-${index}`,
      label: cabinet.description || `Cabinet ${index + 1}`,
      qty: quantity !== null ? `${numOrNull(quantity)} pcs` : null,
      amount: fin(row?.cost) ? row.cost : null,
      held: row?.available === false,
    };
  }));

  // ── Site landscape: one row per recorded material ──
  addGroup("landscape", "Site landscape", arr(landscapeLines).map((line, index) => ({
    key: `land-${index}`,
    label: line?.label || `Material ${index + 1}`,
    qty: fin(line?.sqft) ? fmtQty(line.sqft, "sq ft") : (numOrNull(line?.cells) !== null ? `${numOrNull(line.cells)} cells` : null),
    amount: fin(line?.cost) ? line.cost : null,
    held: landscapePricing?.available === false || !fin(line?.cost),
  })));

  const rowCount = groups.reduce((s, g) => s + g.rows.length, 0);
  return { groups, rowCount };
}

// ─── Missing-input checklist ─────────────────────────────────────────────────
//
// Enumerates the held/unavailable inputs the surface already knows about.
// Blocking channels (design inputs, catalog & settings) are the same lists
// the page's pricingBlocked gate reads; advisory channels (placement,
// construction checks) never block; the held-amounts channel enumerates
// partition buckets whose amount is currently unavailable — it catches held
// components even when the upstream issue list misses them (e.g. wall-cap
// holds, whose issues do not reach the calc channels).
//
// `channelsKnown` distinguishes "issues were checked and none exist" from
// "no issue channel was wired to this panel" — the complete/empty state must
// only be claimed when the channels were actually consulted.

export function buildFoundationInputChecklist({
  totals = {},
  pricingUnavailable = false,
  calc = null,
  issues = null,
  assemblyIssues = null,
} = {}) {
  const src = isRecord(issues) ? issues : isRecord(calc) ? calc : {};
  const channelsKnown = isRecord(issues) || isRecord(calc);
  const catalogIssues = arr(src.catalogIssues);
  const inputIssues = arr(src.inputIssues);
  const constructionWarnings = arr(src.constructionWarnings);
  const placements = arr(assemblyIssues);

  const seen = new Set();
  const items = (list) => arr(list).filter((issue) => {
    const key = `${issue?.code ?? ""}|${issue?.kind ?? ""}|${issue?.index ?? ""}|${issue?.componentId ?? ""}|${issue?.field ?? ""}|${issue?.message ?? issue ?? ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((issue, i) => ({
    key: `${issue?.code ?? "issue"}-${issue?.kind ?? ""}-${issue?.index ?? i}-${issue?.field ?? ""}-${i}`,
    message: String(issue?.message ?? issue),
    code: issue?.code ?? null,
    field: issue?.field ?? null,
  }));

  const heldItems = [];
  for (const [field, label] of FOUNDATION_STICKY_PARTITION_FIELDS) {
    if (!fin(totals?.[field])) {
      heldItems.push({
        key: `held-${field}`,
        message: `${label} — amount unavailable (saved amount shown where recorded)`,
        code: "held_amount",
        field,
      });
    }
  }
  if (isRecord(calc?.delivery) && calc.delivery.pricingUnavailable === true) {
    heldItems.push({
      key: "held-delivery",
      message: "Concrete delivery — held at the saved order snapshot",
      code: "held_amount",
      field: "delivery",
    });
  }
  // Catch-all: pricing paused but no enumerated reason (defensive — the
  // blocked gate should always have a reason, but never render an empty
  // checklist under an unavailable banner).
  if (pricingUnavailable === true && inputIssues.length === 0 && catalogIssues.length === 0 && heldItems.length === 0) {
    heldItems.push({
      key: "held-pricing",
      message: "Pricing is paused — review highlighted inputs and catalog selections",
      code: "pricing_paused",
      field: null,
    });
  }

  const groups = [
    { key: "inputs", label: "Design inputs", severity: "blocking", items: items(inputIssues) },
    { key: "catalog", label: "Catalog & settings", severity: "blocking", items: items(catalogIssues) },
    { key: "assembly", label: "Placement", severity: "advisory", items: items(placements) },
    { key: "checks", label: "Construction checks", severity: "advisory", items: items(constructionWarnings) },
    { key: "held", label: "Held amounts", severity: "held", items: heldItems },
  ].filter((g) => g.items.length > 0);

  const blockingCount = groups.filter((g) => g.severity === "blocking").reduce((s, g) => s + g.items.length, 0);
  const advisoryCount = groups.filter((g) => g.severity === "advisory").reduce((s, g) => s + g.items.length, 0);
  const heldCount = heldItems.length;
  const totalCount = groups.reduce((s, g) => s + g.items.length, 0);

  return {
    groups,
    blockingCount,
    advisoryCount,
    heldCount,
    totalCount,
    channelsKnown,
    // "Complete" is only claimed when the issue channels were actually
    // consulted and nothing is outstanding — never assumed on an unwired panel.
    complete: channelsKnown && totalCount === 0,
  };
}

import { useMemo } from "react";
import { money, calcSignageCabinetPricing } from "./foundationCalc";
import { landscapeSummary } from "./landscapeMaterials";
import { foundationAssemblyIssues } from "./foundationAssemblyModel";
import { foundationEngineEconomics, foundationHasEnginePricing } from "./foundationSellPricing";
import {
  resolveFoundationStickySummary,
  buildFoundationTakeoff,
  buildFoundationInputChecklist,
} from "./foundationTotalsSummary";

const amt = (v) => (Number.isFinite(v) ? money(v) : "Not saved");
const known = (v, d, u) => (Number.isFinite(v) ? `${v.toFixed(d)} ${u}` : "Not saved");

// O-096 (CMP-H05): `project` and `calc` are OPTIONAL — the panel consumes the
// original four props as before and lights up progressively when the page
// wires them (`project={project} calc={calc}` on the existing call site).
// Unwired, the panel still shows the cost column, the totals-quantity
// takeoff, and the held-amounts checklist — it never claims the issue
// channels were checked when they were not passed.
export default function FoundationTotals({ totals, pricingUnavailable = false, savedSectionTotal = null, sectionTotal = null, project = null, calc = null }) {
  const wallMortar = [totals.total_wall_cost, totals.total_brick_cost, totals.total_fill_cost].every(Number.isFinite)
    ? totals.total_wall_cost - totals.total_brick_cost - totals.total_fill_cost
    : null;
  // Saved-vs-current reconciliation (CMP-A10): `savedSectionTotal` is the
  // acknowledged record's persisted split-total sum (the same number the
  // linked estimate stored as live_total_snapshot at the last Builder save);
  // `sectionTotal` is the live recalculation including cabinets + landscape.
  // Advisory only — never blocks — and |delta| <= $0.005 never fires, the
  // same tolerance builderService.sameNumber / useSectionSync / ProductRow
  // already use for frozen-vs-live snapshot comparisons.
  const saved = Number.isFinite(savedSectionTotal) ? savedSectionTotal : null;
  const currentKnown = Number.isFinite(sectionTotal);
  const savedDelta = saved !== null && currentKnown ? sectionTotal - saved : null;
  const savedDiffers = savedDelta !== null && Math.abs(savedDelta) > 0.005;

  // Separate cost/sell/margin (CMP-H05). Sell precedence mirrors
  // customerPricing.sourceProjectEconomics' foundation branch: engine >
  // applied tier snapshot > override > markup %. Computed sells (engine +
  // markup) require the live cost — a held amount is never multiplied into a
  // fabricated customer price. The engine seam only runs when the record
  // actually carries config (foundationHasEnginePricing — the same cheap
  // detector CustomerPricingPanel uses).
  const summary = useMemo(
    () => resolveFoundationStickySummary({
      sectionTotal,
      savedSectionTotal,
      pricingUnavailable,
      project,
      engineResolver: project && foundationHasEnginePricing(project) ? foundationEngineEconomics : null,
    }),
    [sectionTotal, savedSectionTotal, pricingUnavailable, project]
  );

  // Itemized takeoff (CMP-H05): per-component quantity+amount rows. Falls
  // back to the totals quantity snapshot when `calc`/`project` aren't wired.
  const takeoff = useMemo(
    () => buildFoundationTakeoff({
      totals,
      items: calc?.items, itemPricing: calc?.itemPricing,
      walls: calc?.walls, wallPricing: calc?.wallPricing,
      poles: calc?.poles, polePricing: calc?.polePricing,
      wallCaps: calc?.wallCaps,
      equipment: calc?.equipment, equipmentPricing: calc?.equipmentPricing,
      delivery: calc?.delivery,
      cabinets: project?.signage_cabinets,
      cabinetRows: project ? calcSignageCabinetPricing(project.signage_cabinets) : null,
      landscapeLines: project ? landscapeSummary(project.landscape).lines : null,
      landscapePricing: calc?.landscapePricing,
    }),
    [totals, calc, project]
  );

  // Missing-input checklist (CMP-H05): the blocking channels are exactly the
  // lists the page's pricingBlocked gate reads (calc.inputIssues +
  // calc.catalogIssues); placement + construction warnings are advisory; the
  // held-amounts channel is derived from the partition totals so held
  // buckets surface even where upstream issue lists don't reach (wall caps).
  const checklist = useMemo(
    () => buildFoundationInputChecklist({
      totals,
      pricingUnavailable,
      calc,
      assemblyIssues: project ? foundationAssemblyIssues(project) : null,
    }),
    [totals, pricingUnavailable, calc, project]
  );

  const lines = [
    ["Concrete", totals.total_concrete_cost],
    ["Rebar", totals.total_rebar_cost],
    ["Excavation", totals.total_excavation_cost],
    ["Forming materials", totals.total_forming_materials_cost],
    ["Labor", totals.total_labor_cost],
    ["Poles", totals.total_pole_cost],
    ["Pole painting", totals.total_pole_painting_cost],
    ["Wall material", totals.total_brick_cost],
    ["Internal fill wall", totals.total_fill_cost],
    ["Wall mortar + labor", wallMortar],
    ["Wall caps", totals.total_wall_cap_cost],
    ["Equipment", totals.total_equipment_cost],
  ];

  const marginText = summary.margin.amount !== null
    ? `${money(summary.margin.amount)}${summary.margin.pct !== null ? ` · ${summary.margin.pct.toFixed(1)}%` : ""}`
    : "—";

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 sticky top-4">
      <h2 className="font-semibold text-gray-900 mb-3">Section Total</h2>
      {pricingUnavailable && <p className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">Saved/known amounts only; current pricing is incomplete.</p>}

      {/* Separate cost / sell / margin (O-096). Sell side carries its
          precedence source so a tier/engine/override number never masquerades
          as the manual baseline; held sides render — instead of fabricating. */}
      <div className="grid grid-cols-3 gap-2 mb-3 text-center">
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Cost (internal)</div>
          <div className="text-sm font-semibold text-gray-800">
            {summary.cost.value !== null ? money(summary.cost.value) : "Not saved"}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.cost.source === "saved" ? "acknowledged saved" : summary.cost.source === "live" ? "current" : ""}
          </div>
        </div>
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Sell (customer)</div>
          <div className="text-sm font-semibold text-gray-800">
            {summary.sell.value !== null ? money(summary.sell.value) : "—"}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.sell.value !== null ? summary.sell.label : (summary.projectLinked ? "not recorded" : "")}
          </div>
        </div>
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Margin</div>
          <div className={`text-sm font-semibold ${summary.margin.amount !== null && summary.margin.amount < 0 ? "text-red-700" : "text-gray-800"}`}>
            {marginText}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.margin.basis === "saved" ? "vs saved cost" : summary.margin.basis === "live" ? "sell − cost" : ""}
          </div>
        </div>
      </div>
      {summary.acknowledged?.differs && (
        <p role="status" className="mb-3 rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Tier snapshot recorded internal cost {money(summary.acknowledged.cost)} → acknowledged margin {money(summary.acknowledged.marginAmount)}{summary.acknowledged.marginPct !== null ? ` (${summary.acknowledged.marginPct.toFixed(1)}%)` : ""}; the cost column above reflects the {summary.cost.source === "saved" ? "saved" : "current"} section total.
        </p>
      )}

      <div className="grid grid-cols-3 gap-2 mb-3 text-center">
        {[
          ["Concrete", known(totals.total_concrete_volume_cy, 2, "CY")],
          ["Excavation", known(totals.total_excavation_volume_cy, 2, "CY")],
          ["Labor", known(totals.total_labor_hours, 1, "hr")],
        ].map(([label, value]) => (
          <div key={label} className="bg-slate-50 rounded-lg py-2">
            <div className="text-[10px] uppercase tracking-wide text-gray-400">{label}</div>
            <div className="text-sm font-semibold text-gray-800">{value}</div>
          </div>
        ))}
      </div>

      <div className="space-y-1.5 text-sm border-t border-gray-100 pt-3">
        {lines.map(([label, value]) => (
          <div key={label} className="flex justify-between text-gray-600">
            <span>{label}</span>
            <span>{amt(value)}</span>
          </div>
        ))}
        <div className="flex justify-between font-bold text-gray-900 text-base border-t border-gray-200 pt-2">
          <span>Total</span>
          <span className="text-red-600">{pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : money(totals.grand_total)}</span>
        </div>
      </div>

      {/* Missing-input checklist (O-096): blocking channels auto-expand;
          advisory and held channels stay collapsed under the count. */}
      {checklist.complete ? (
        <p role="status" className="mt-3 rounded-sm border border-emerald-200 bg-emerald-50 px-2 py-1 text-[11px] font-semibold text-emerald-800">
          All inputs recorded — no missing or held amounts.
        </p>
      ) : checklist.totalCount > 0 ? (
        <details className="mt-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1" open={checklist.blockingCount > 0}>
          <summary className="cursor-pointer select-none text-[11px] font-semibold text-amber-800">
            Missing inputs &amp; held amounts —{" "}
            {[
              checklist.blockingCount > 0 ? `${checklist.blockingCount} blocking` : null,
              checklist.advisoryCount > 0 ? `${checklist.advisoryCount} advisory` : null,
              checklist.heldCount > 0 ? `${checklist.heldCount} held` : null,
            ].filter(Boolean).join(", ")}
          </summary>
          <div className="mt-1 max-h-56 space-y-2 overflow-y-auto">
            {checklist.groups.map((g) => (
              <div key={g.key}>
                <div className={`text-[10px] uppercase tracking-wide ${g.severity === "blocking" ? "text-amber-700" : g.severity === "held" ? "text-gray-500" : "text-blue-700"}`}>
                  {g.label} ({g.items.length})
                </div>
                <ul className={`list-disc pl-4 text-[11px] ${g.severity === "advisory" ? "text-blue-900" : "text-amber-900"}`}>
                  {g.items.map((it) => <li key={it.key}>{it.message}</li>)}
                </ul>
              </div>
            ))}
          </div>
        </details>
      ) : !checklist.channelsKnown ? (
        <p className="mt-3 text-[11px] text-gray-400">No held amounts in the totals snapshot.</p>
      ) : null}

      {/* Itemized takeoff (O-096): per-component quantity + amount rows —
          collapsible so the sticky card stays compact. */}
      {takeoff.rowCount > 0 && (
        <details className="mt-3 rounded-sm border border-gray-200 bg-slate-50 px-2 py-1">
          <summary className="cursor-pointer select-none text-[11px] font-semibold text-gray-700">
            Itemized takeoff — {takeoff.rowCount} row{takeoff.rowCount === 1 ? "" : "s"}
          </summary>
          <div className="mt-1 max-h-64 space-y-2 overflow-y-auto">
            {takeoff.groups.map((g) => (
              <div key={g.key}>
                <div className="text-[10px] uppercase tracking-wide text-gray-400">{g.label}</div>
                <ul className="space-y-0.5">
                  {g.rows.map((r) => (
                    <li key={r.key} className="flex justify-between gap-2 text-[11px] text-gray-700">
                      <span className="min-w-0">
                        {r.label}
                        {r.held && <span className="ml-1 font-semibold text-amber-700">(saved)</span>}
                        {r.qty && <span className="block text-[10px] text-gray-400">{r.qty}</span>}
                      </span>
                      <span className="whitespace-nowrap">{r.amount !== null ? money(r.amount) : r.held ? "Not saved" : "—"}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </details>
      )}

      {saved !== null && !currentKnown && (
        <div role="status" className="mt-3 rounded-sm border border-gray-300 bg-slate-50 px-2 py-1 text-[11px] text-gray-700">
          Saved section total {money(saved)} — current pricing unavailable.
        </div>
      )}
      {savedDiffers && (
        <div role="status" className="mt-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">
          Saved {money(saved)} — current {money(sectionTotal)} ({savedDelta > 0 ? "+" : "−"}{money(Math.abs(savedDelta))}) — recalculated from current inputs and catalog. Save to update the estimate.
        </div>
      )}
    </div>
  );
}

import { Input } from "@/components/ui/input";
import { money } from "./foundationCalc";
import { foundationHasEnginePricing } from "./foundationSellPricing";

export default function CustomerPricingPanel({ cost, project, onChange }) {
  const markup = project.customer_markup_percent || 0;
  const override = project.customer_price_override;
  const marked = cost * (1 + markup / 100);
  const price = override > 0 ? override : marked;
  const margin = price > 0 ? ((price - cost) / price) * 100 : 0;

  // Sell-side precedence (CMP-A10; mirrors sourceProjectEconomics' foundation
  // branch in customerPricing.js): explicit pricing-engine config resolves
  // the live customer price first; absent engine config an applied Markup
  // Tier snapshot (customer_pricing.applied === true with a numeric total)
  // replaces it wholesale; otherwise the manual baseline below wins —
  // customer_price_override > 0 beats cost x (1 + markup %). `price` here is
  // therefore the MANUAL baseline: honest whenever neither upstream layer is
  // engaged, advisory-shadowed otherwise.
  const enginePriced = foundationHasEnginePricing(project);
  const tierTotal = project.customer_pricing?.applied === true && Number.isFinite(Number(project.customer_pricing?.total))
    ? Number(project.customer_pricing.total)
    : null;
  const tierShadowsBaseline = !enginePriced && tierTotal !== null && Math.abs(tierTotal - price) > 0.005;

  return (
    <div className="max-w-xl bg-white rounded-sm border border-gray-200 p-4 space-y-3">
      <div>
        <h3 className="text-[13px] font-bold text-gray-900">Customer Pricing</h3>
        <p className="text-[11px] text-gray-400">
          Internal cost stays private — the customer price below is what flows to the estimate presentation.
        </p>
      </div>

      {enginePriced && (
        <p role="status" className="rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Pricing-engine configuration on this project resolves the live customer price (precedence: pricing engine → applied tier → price override → markup %). The manual markup/override below still applies to components without engine config.
        </p>
      )}
      {tierShadowsBaseline && (
        <p role="status" className="rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Applied Tier {project.customer_pricing?.tier_number} pricing ({money(tierTotal)}) is the live customer price — the markup/override below is stored but not used while a tier is applied. Editing either field switches this section back to manual pricing.
        </p>
      )}

      <div className="flex justify-between text-[12px] text-gray-600">
        <span>Internal section cost</span>
        <span className="font-semibold text-gray-900">{money(cost)}</span>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <label className="text-[11px] text-gray-500">
          Markup %
          <Input
            type="number"
            value={markup}
            onChange={(e) => onChange({ customer_markup_percent: parseFloat(e.target.value) || 0 })}
          />
        </label>
        <label className="text-[11px] text-gray-500">
          Price override
          <Input
            type="number"
            value={override ?? ""}
            placeholder="Use markup"
            onChange={(e) => onChange({ customer_price_override: parseFloat(e.target.value) || 0 })}
          />
        </label>
      </div>

      <div className="border-t border-gray-100 pt-3 space-y-1 text-[12px]">
        <div className="flex justify-between text-gray-600">
          <span>Markup amount</span>
          <span>{money(marked - cost)}</span>
        </div>
        <div className="flex justify-between text-gray-600">
          <span>Gross margin</span>
          <span>{margin.toFixed(1)}%</span>
        </div>
        {/* O-096: when the applied tier is the live sell, the acknowledged
            margin pair comes straight from the customer_pricing snapshot
            fields (total vs raw_subtotal) — never recomputed from the manual
            baseline it shadows. */}
        {tierShadowsBaseline && Number.isFinite(Number(project.customer_pricing?.raw_subtotal)) && (
          <div className="flex justify-between text-blue-700">
            <span>Tier {project.customer_pricing?.tier_number} snapshot margin (acknowledged)</span>
            <span>
              {money(tierTotal - Number(project.customer_pricing.raw_subtotal))}
              {tierTotal > 0 ? ` · ${(((tierTotal - Number(project.customer_pricing.raw_subtotal)) / tierTotal) * 100).toFixed(1)}%` : ""}
            </span>
          </div>
        )}
        <div className="flex justify-between text-[14px] font-bold text-gray-900 pt-1">
          <span>Customer price</span>
          <span className="text-red-700">{money(price)}</span>
        </div>
      </div>
    </div>
  );
}

